NAME = 'Wulfila: Bishop Wulfila Gothic Bible'
BOOK = 'I Thessalonians'

CHAPTERS = {
    2: {
        10: '.... 𐌾𐌰𐌷 𐌲𐌿𐌸, 𐍈𐌰𐌹𐍅𐌰 𐍅𐌴𐌹𐌷𐌰𐌱𐌰 𐌾𐌰𐌷 𐌲𐌰𐍂𐌰𐌹𐌷𐍄𐌰𐌱𐌰 𐌾𐌰𐌷 𐌿𐌽𐍆𐌰𐌹𐍂𐌹𐌽𐍉𐌳𐌰𐌱𐌰 𐌹𐌶𐍅𐌹𐍃 𐌸𐌰𐌹𐌼 𐌲𐌰𐌻𐌰𐌿𐌱𐌾𐌰𐌽𐌳𐌰𐌼 𐍅𐌴𐍃𐌿𐌼,',
        11: '𐍃𐍅𐌰𐍃𐍅𐌴 𐍅𐌹𐍄𐌿𐌸 𐌰𐌹𐌽𐍈𐌰𐍂𐌾𐌰𐌽𐍉𐌷 𐌹𐌶𐍅𐌰𐍂𐌰, 𐍃𐍅𐌴 𐌰𐍄𐍄𐌰 𐌱𐌰𐍂𐌽𐌰 𐍃𐌴𐌹𐌽𐌰, 𐌱𐌹𐌳𐌾𐌰𐌽𐌳𐌰𐌽𐍃 𐌹𐌶𐍅𐌹𐍃 𐌾𐌰𐌷 𐌲𐌰𐌸𐌻𐌰𐌹𐌷𐌰𐌽𐌳𐌰𐌽𐍃,',
        12: '𐌾𐌰𐌷 𐍅𐌴𐌹𐍄𐍅𐍉𐌳𐌾𐌰𐌽𐌳𐌰𐌽𐍃 𐌳𐌿 𐌲𐌰𐌲𐌲𐌰𐌽 𐌹𐌶𐍅𐌹𐍃 𐍅𐌰𐌹𐍂𐌸𐌰𐌱𐌰 𐌲𐌿𐌳𐌹𐍃, 𐍃𐌰𐌴𐌹 𐌻𐌰𐌸𐍉𐌳𐌰 𐌹𐌶𐍅𐌹𐍃 𐌳𐌿 𐍃𐌴𐌹𐌽𐌰𐌹 𐌸𐌹𐌿𐌳𐌰𐌽𐌲𐌰𐍂𐌳𐌾𐌰𐌹 𐌾𐌰𐌷 𐍅𐌿𐌻𐌸𐌰𐌿.',
        13: '𐌳𐌿𐌸𐌴 𐌾𐌰𐌷 𐍅𐌴𐌹𐍃 𐌰𐍅𐌹𐌻𐌹𐌿𐌳𐍉𐌼 𐌲𐌿𐌳𐌰 𐌿𐌽𐍃𐍅𐌴𐌹𐌱𐌰𐌽𐌳𐌰𐌽𐍃, 𐌿𐌽𐍄𐌴 𐌽𐌹𐌼𐌰𐌽𐌳𐌰𐌽𐍃 𐌰𐍄 𐌿𐌽𐍃 𐍅𐌰𐌿𐍂𐌳 𐌷𐌰𐌿𐍃𐌴𐌹𐌽𐌰𐌹𐍃 𐌲𐌿𐌳𐌹𐍃 𐌰𐌽𐌳𐌽𐌴𐌼𐌿𐌸 𐌽𐌹 𐍃𐍅𐌰𐍃𐍅𐌴 𐍅𐌰𐌿𐍂𐌳 𐌼𐌰𐌽𐌽𐌴, 𐌰𐌺 𐍃𐍅𐌰𐍃𐍅𐌴 𐌹𐍃𐍄 𐍃𐌿𐌽𐌾𐌰𐌱𐌰 𐍅𐌰𐌿𐍂𐌳 𐌲𐌿𐌳𐌹𐍃, 𐌸𐌰𐍄𐌴𐌹 𐌾𐌰𐌷 𐍅𐌰𐌿𐍂𐌺𐌴𐌹 𐌹𐌽 𐌹𐌶𐍅𐌹𐍃 𐌾𐌿𐌶𐌴𐌹 𐌲𐌰𐌻𐌰𐌿𐌱𐌴𐌹𐌸.',
        14: '𐌾𐌿𐍃 𐌰𐌿𐌺 𐌲𐌰𐌻𐌴𐌹𐌺𐍉𐌽𐌳𐌰𐌽𐍃 𐍅𐌰𐌿𐍂𐌸𐌿𐌸, 𐌱𐍂𐍉𐌸𐍂𐌾𐌿𐍃, 𐌰𐌹𐌺𐌺𐌻𐌴𐍃𐌾𐍉𐌼 𐌲𐌿𐌳𐌹𐍃 𐌸𐌰𐌹𐌼 𐍅𐌹𐍃𐌰𐌽𐌳𐌴𐌹𐌼 𐌹𐌽 𐌹𐌿𐌳𐌰𐌹𐌰 𐌹𐌽 𐍇𐍂𐌹𐍃𐍄𐌰𐌿 𐌹𐌴𐍃𐌿, 𐌿𐌽𐍄𐌴 𐌸𐌰𐍄𐌰 𐍃𐌰𐌼𐍉 𐍅𐌿𐌽𐌽𐌿𐌸 𐌾𐌰𐌷 𐌾𐌿𐍃 𐍆𐍂𐌰𐌼 𐌹𐌶𐍅𐌰𐍂𐌰𐌹𐌼 𐌹𐌽𐌺𐌿𐌽𐌾𐌰𐌼 𐍃𐍅𐌰𐍃𐍅𐌴 𐌾𐌰𐌷 𐍅𐌴𐌹𐍃 𐍆𐍂𐌰𐌼 𐌹𐌿𐌳𐌰𐌹𐌿𐌼,',
        15: '𐌸𐌰𐌹𐌴𐌹 𐌾𐌰𐌷 𐍆𐍂𐌰𐌿𐌾𐌹𐌽 𐌿𐍃𐌵𐌴𐌼𐌿𐌽 𐌹𐌴𐍃𐌿𐌰 𐌾𐌰𐌷 𐍃𐍅𐌴𐍃𐌰𐌹𐌼 𐍀𐍂𐌰𐌿𐍆𐌴𐍄𐌿𐌼 𐌾𐌰𐌷 𐌿𐌽𐍃 𐍆𐍂𐌰𐍅𐍂𐌴𐌺𐌿𐌽 𐌾𐌰𐌷 𐌲𐌿𐌳𐌰 𐌽𐌹 𐌲𐌰𐌻𐌴𐌹𐌺𐌰𐌽𐌳𐌰𐌽𐍃 𐌾𐌰𐌷 𐌰𐌻𐌻𐌰𐌹𐌼 𐌼𐌰𐌽𐌽𐌰𐌼 𐌰𐌽𐌳𐌰𐌽𐌴𐌹𐌸𐌰𐌽𐍃 𐍃𐌹𐌽𐌳,',
        16: '𐍅𐌰𐍂𐌾𐌰𐌽𐌳𐌰𐌽𐍃 𐌿𐌽𐍃 𐌳𐌿 𐌸𐌹𐌿𐌳𐍉𐌼 𐍂𐍉𐌳𐌾𐌰𐌽 𐌴𐌹 𐌲𐌰𐌽𐌹𐍃𐌰𐌹𐌽𐌰, 𐌰𐌺𐌴𐌹 𐌳𐌿 𐌿𐍃𐍆𐌿𐌻𐌻𐌾𐌰𐌽 𐍃𐌴𐌹𐌽𐍉𐍃 𐍆𐍂𐌰𐍅𐌰𐌿𐍂𐌷𐍄𐌹𐌽𐍃 𐍃𐌹𐌽𐍄𐌴𐌹𐌽𐍉; 𐌰𐌸𐌸𐌰𐌽 𐍃𐌽𐌰𐌿𐌷 𐌰𐌽𐌰 𐌹𐌽𐍃 𐌷𐌰𐍄𐌹𐍃 𐌲𐌿𐌳𐌹𐍃 𐌿𐌽𐌳 𐌰𐌽𐌳𐌹.',
        17: '𐌰𐌸𐌸𐌰𐌽 𐍅𐌴𐌹𐍃, 𐌱𐍂𐍉𐌸𐍂𐌾𐌿𐍃, 𐌲𐌰𐌰𐌹𐌽[𐌰𐌽]𐌰𐌹𐌳𐌰𐌹 𐌰𐍆 𐌹𐌶𐍅𐌹𐍃 𐌳𐌿 𐌼𐌴𐌻𐌰 𐍈𐌴𐌹𐌻𐍉𐍃, 𐌰𐌽𐌳𐍅𐌰𐌹𐍂𐌸𐌾𐌰 𐌽𐌹 𐌷𐌰𐌹𐍂𐍄𐌹𐌽, 𐌿𐍆𐌰𐍂𐌰𐍃𐍃𐌰𐌿 𐍃𐌽𐌹𐌿𐌼𐌹𐌳𐌴𐌳𐌿𐌼 𐌰𐌽𐌳𐌰𐌿𐌲𐌹 𐌹𐌶𐍅𐌰𐍂[𐌰] 𐌲𐌰𐍃𐌰𐌹𐍈𐌰𐌽 𐌹𐌽 𐌼𐌰𐌽𐌰𐌲𐌰𐌼𐌼𐌰 𐌻𐌿𐍃𐍄𐌰𐌿.',
        18: '𐌿𐌽𐍄𐌴 𐍅𐌹𐌻𐌳𐌴𐌳𐌿𐌼 𐌵𐌹𐌼𐌰𐌽 𐌰𐍄 𐌹𐌶𐍅𐌹𐍃, 𐌹𐌺 𐍂𐌰𐌹𐌷𐍄𐌹𐍃 𐍀𐌰𐍅𐌻𐌿𐍃 𐌾𐌰𐌷 𐌰𐌹𐌽𐌰𐌼𐌼𐌰 𐍃𐌹𐌽𐌸𐌰 𐌾𐌰𐌷 𐍄𐍅𐌰𐌹𐌼, 𐌾𐌰𐌷 𐌰𐌽𐌰𐌻𐌰𐍄𐌹𐌳𐌰 𐌿𐌽𐍃 𐍃𐌰𐍄𐌰𐌽𐌰.',
        19: '𐍈𐌰 𐌰𐌿𐌺 𐌹𐍃𐍄 𐌿𐌽𐍃𐌰𐍂𐌰 𐍅𐌴𐌽𐍃 𐌰𐌹𐌸𐌸𐌰𐌿 𐍆𐌰𐌷𐌴𐌸𐍃 𐌰𐌹𐌸𐌸𐌰𐌿 𐍅𐌰𐌹𐍀𐍃 𐍈𐍉𐍆𐍄𐌿𐌻𐌾𐍉𐍃, 𐌽𐌹𐌿 𐌾𐌿𐍃 𐌹𐌽 𐌰𐌽𐌳𐍅𐌰𐌹𐍂𐌸𐌾𐌰 𐍆𐍂𐌰𐌿𐌾𐌹𐌽𐍃 𐌿𐌽𐍃𐌰𐍂𐌹𐍃 𐌹𐌴𐍃𐌿𐌹𐍃 𐍇𐍂𐌹𐍃𐍄𐌰𐌿𐍃 𐌹𐌽 𐌹𐍃 𐌵𐌿𐌼𐌰?',
        20: '𐌾𐌿𐍃 𐌰𐌿𐌺 𐍃𐌹𐌿𐌸 𐍅𐌿𐌻𐌸𐌿𐍃 𐌿𐌽𐍃𐌰𐍂 𐌾𐌰𐌷 𐍆𐌰𐌷𐌴𐌸𐍃.',
    },
    3: {
        1: '𐌹𐌽 𐌸𐌹𐌶𐌴𐌹 𐌾𐌿 𐌽𐌹 𐌿𐍃𐌸𐌿𐌻𐌰𐌽𐌳𐌰𐌽𐍃 𐌸𐌰𐌽𐌰𐌼𐌰𐌹𐍃, 𐌲𐌰𐌻𐌴𐌹𐌺𐌰𐌹𐌳𐌰 𐌿𐌽𐍃 𐌴𐌹 𐌱𐌹𐌻𐌹𐌸𐌰𐌽𐌰𐌹 𐍅𐌴𐍃𐌴𐌹𐌼𐌰 𐌹𐌽 𐌰𐌸𐌴𐌹𐌽𐌹𐌼 𐌰𐌹𐌽𐌰𐌹.',
        2: '𐌾𐌰𐌷 𐌹𐌽𐍃𐌰𐌽𐌳𐌹𐌳𐌴𐌳𐌿𐌼 𐍄𐌴𐌹𐌼𐌰𐌿𐌸𐌰𐌹𐌿, 𐌱𐍂𐍉𐌸𐌰𐍂 𐌿𐌽𐍃𐌰𐍂𐌰𐌽𐌰 𐌾𐌰𐌷 𐌰𐌽𐌳𐌱𐌰𐌷𐍄 𐌲𐌿𐌳𐌹𐍃 𐌹𐌽 𐌰𐌹𐍅𐌰𐌲𐌲𐌴𐌻𐌾𐍉𐌽 𐍇𐍂𐌹𐍃𐍄𐌰𐌿𐍃, 𐌴𐌹 𐌹𐌶𐍅𐌹𐍃 𐌲𐌰𐍄𐌿𐌻𐌲𐌾𐌰𐌹 𐌾𐌰𐌷 𐌱𐌹𐌳𐌾𐌰𐌹 𐌱𐌹 𐌲𐌰𐌻𐌰𐌿𐌱𐌴𐌹𐌽 𐌹𐌶𐍅𐌰𐍂𐌰,',
        3: '𐌴𐌹 𐌽𐌹 𐌰𐌹𐌽𐍃𐌷𐌿𐌽 𐌰𐍆𐌰𐌲𐌾𐌰𐌹𐌳𐌰𐌿 𐌹𐌽 𐌸𐌰𐌹𐌼 𐌰𐌲𐌲𐍅𐌹𐌸𐍉𐌼; 𐍃𐌹𐌻𐌱𐌰𐌽𐍃 𐌰𐌿𐌺 𐍅𐌹𐍄𐌿𐌸 𐌸𐌰𐍄𐌴𐌹 𐌳𐌿 𐌸𐌰𐌼𐌼𐌰 𐍃𐌰𐍄𐌹𐌳𐌰𐌹 𐍃𐌹𐌾𐌿𐌼.',
        4: '𐌾𐌰𐌷 𐌰𐌿𐌺 𐌸𐌰𐌽 𐍅𐌴𐍃𐌿𐌼 𐌰𐍄 𐌹𐌶𐍅𐌹𐍃, 𐍆𐌰𐌿𐍂𐌰𐌵𐌴𐌸𐌿𐌼 𐌹𐌶𐍅𐌹𐍃 𐌸𐌰𐍄𐌴𐌹 𐌰𐌽𐌰𐍅𐌰𐌹𐍂𐌸 𐍅𐌰𐍃 𐌿𐌽𐍃 𐌳𐌿 𐍅𐌹𐌽𐌽𐌰𐌽 𐌰𐌲𐌻𐌹𐌸𐍉𐍃, 𐍃𐍅𐌰𐍃𐍅𐌴 𐌾𐌰𐌷 𐍅𐌰𐍂𐌸 𐌾𐌰𐌷 𐍅𐌹𐍄𐌿𐌸.',
        5: '𐌳𐌿𐌸𐌸𐌴 𐌾𐌰𐌷 𐌹𐌺 𐌾𐌿 𐌽𐌹 𐌿𐍃𐌸𐌿𐌻𐌰𐌽𐍃 𐌹𐌽𐍃𐌰𐌽𐌳𐌹𐌳𐌰 𐌳𐌿 𐌿𐍆𐌺𐌿𐌽𐌽𐌰𐌽 𐌲𐌰𐌻𐌰𐌿𐌱𐌴𐌹𐌽 𐌹𐌶𐍅𐌰𐍂𐌰, 𐌹𐌱𐌰𐌹 𐌰𐌿𐍆𐍄𐍉 𐌿𐍃𐍆𐌰𐌹𐍆𐍂𐌰𐌹𐍃𐌹 𐌹𐌶𐍅𐌹𐍃 𐍃𐌰 𐍆𐍂𐌰𐌹𐍃𐌰𐌽𐌳𐍃 𐌾𐌰𐌷 𐍃𐍅𐌰𐍂𐌴 𐍅𐌰𐌹𐍂𐌸𐌰𐌹 𐌰𐍂𐌱𐌰𐌹𐌸𐍃 𐌿𐌽𐍃𐌰𐍂𐌰.',
        6: '𐌰𐌸𐌸𐌰𐌽 𐌽𐌿 𐌰𐍄 𐌵𐌹𐌼𐌰𐌽𐌳𐌹𐌽 𐍄𐌴𐌹𐌼𐌰𐌿𐌸𐌰𐌹𐌿 𐌰𐍄 𐌿𐌽𐍃𐌹𐍃 𐍆𐍂𐌰𐌼 𐌹𐌶𐍅𐌹𐍃 𐌾𐌰𐌷 𐌲𐌰𐍄𐌴𐌹𐌷𐌰𐌽𐌳𐌹𐌽 𐌿𐌽𐍃 𐌲𐌰𐌻𐌰𐌿𐌱𐌴𐌹𐌽 𐍆𐍂𐌹𐌰𐌸𐍅𐌰 𐌹𐌶𐍅𐌰𐍂𐌰, 𐌾𐌰𐌷 𐌸𐌰𐍄𐌴𐌹 𐌲𐌰𐌼𐌹𐌽𐌸𐌹 𐌿𐌽𐍃𐌰𐍂 𐌷𐌰𐌱𐌰𐌹𐌸 𐌲𐍉𐌳 𐍃𐌹𐌽𐍄𐌴𐌹𐌽𐍉, 𐌲𐌰𐌹𐍂𐌽𐌾𐌰𐌽𐌳𐌰𐌽𐍃 𐌿𐌽𐍃 𐌲𐌰𐍃𐌰𐌹𐍈𐌰𐌽, 𐍃𐍅𐌰𐍃𐍅𐌴 𐌾𐌰𐌷 𐍅𐌴𐌹𐍃 𐌹𐌶𐍅𐌹𐍃,',
        7: '𐌹𐌽𐌿𐌷 𐌸𐌹𐍃 𐌲𐌰𐌸𐍂𐌰𐍆𐍃𐍄𐌹𐌳𐌰𐌹 𐍃𐌹𐌾𐌿𐌼, 𐌱𐍂𐍉𐌸𐍂𐌾𐌿𐍃, 𐍆𐍂𐌰𐌼 𐌹𐌶𐍅𐌹𐍃 𐌰𐌽𐌰 𐌰𐌻𐌻𐌰𐌹 𐌽𐌰𐌿𐌸𐌰𐌹 𐌾𐌰𐌷 𐌰𐌲𐌻𐍉𐌽 𐌿𐌽𐍃𐌰𐍂𐌰𐌹 𐌹𐌽 𐌹𐌶𐍅𐌰𐍂𐌰𐌹𐌶𐍉𐍃 𐌲𐌰𐌻𐌰𐌿𐌱𐌴𐌹𐌽𐌰𐌹𐍃;',
        8: '𐌿𐌽𐍄𐌴 𐍃𐌰𐌹 𐌻𐌹𐌱𐌰𐌼, 𐌾𐌰𐌱𐌰𐌹 𐌾𐌿𐍃 𐌲𐌰𐍃𐍄𐌰𐌽𐌳𐌹𐌸 𐌹𐌽 𐍆𐍂𐌰𐌿𐌾𐌹𐌽.',
        9: '𐍈𐌰 𐌰𐌿𐌺 𐌰𐍅𐌹𐌻𐌹𐌿𐌳𐌴 𐌼𐌰𐌲𐌿𐌼 𐌿𐍃𐌲𐌹𐌻𐌳𐌰𐌽 [𐍆𐍂𐌰𐌿𐌾𐌹𐌽] 𐌲𐌿𐌳𐌰 𐌱𐌹 𐌹𐌶𐍅𐌹𐍃 𐌰𐌽𐌰 𐌰𐌻𐌻𐌰𐌹 𐍆𐌰𐌷𐌴𐌳𐌰𐌹 𐌸𐌹𐌶𐌰𐌹𐌴𐌹 𐍆𐌰𐌲𐌹𐌽𐍉𐌼 𐌹𐌽 𐌹𐌶𐍅𐌰𐍂𐌰 𐍆𐌰𐌿𐍂𐌰 𐌲𐌿𐌳𐌰 𐌿𐌽𐍃𐌰𐍂𐌰𐌼𐌼𐌰,',
        10: '𐌽𐌰𐌷𐍄 𐌾𐌰𐌷 𐌳𐌰𐌲𐌰 𐌿𐍆𐌰𐍂𐌰𐍃𐍃𐌰𐌿 𐌱𐌹𐌳𐌾𐌰𐌽𐌳𐌰𐌽𐍃 𐌴𐌹 𐌲𐌰𐍃𐌰𐌹𐍈𐌰𐌹𐌼𐌰 𐌰𐌽𐌳𐍅𐌰𐌹𐍂𐌸𐌾𐌰 𐌹𐌶𐍅𐌰𐍂𐌰 𐌾𐌰𐌷 𐌿𐍃𐍄𐌹𐌿𐌷𐌰𐌹𐌼𐌰 𐍅𐌰𐌽𐌹𐌽𐌰𐍃𐍃𐌿 𐌲𐌰𐌻𐌰𐌿𐌱𐌴𐌹𐌽𐌰𐌹𐍃 𐌹𐌶𐍅𐌰𐍂𐌰𐌹𐌶𐍉𐍃?',
        11: '𐌰𐌸𐌸𐌰𐌽 𐍃𐌹𐌻𐌱𐌰 𐌲𐌿𐌸 𐌾𐌰𐌷 𐌰𐍄𐍄𐌰 𐌿𐌽𐍃𐌰𐍂 𐌾𐌰𐌷 𐍆𐍂𐌰𐌿𐌾𐌰 𐌿𐌽𐍃𐌰𐍂 𐌹𐌴𐍃𐌿𐍃 𐍇𐍂𐌹𐍃𐍄𐌿𐍃 𐌲𐌰𐍂𐌰𐌹𐌷𐍄𐌾𐌰𐌹 𐍅𐌹𐌲 𐌿𐌽𐍃𐌰𐍂𐌰𐌽𐌰 𐌳𐌿 𐌹𐌶𐍅𐌹𐍃.',
        12: '𐌰𐌸𐌸𐌰𐌽 𐌹𐌶𐍅𐌹𐍃 𐍆𐍂𐌰𐌿𐌾𐌰 𐌼𐌰𐌽𐌰𐌲𐌾𐌰𐌹 𐌾𐌰𐌷 𐌲𐌰𐌽𐍉𐌷𐌽𐌰𐌽 𐌲𐌰𐍄𐌰𐌿𐌾𐌰𐌹 𐍆𐍂𐌹𐌰𐌸𐍅𐌰𐌹 𐌹𐌽 𐌹𐌶𐍅𐌹𐍃 𐌼𐌹𐍃𐍃𐍉 𐌾𐌰𐌷 𐌰𐌻𐌻𐌰𐌽𐍃 𐍃𐍅𐌰𐍃𐍅𐌴 𐌾𐌰𐌷 𐍅𐌴𐌹𐍃 𐌹𐌽 𐌹𐌶𐍅𐌹𐍃,',
        13: '𐌳𐌿 𐍄𐌿𐌻𐌲𐌾𐌰𐌽 𐌷𐌰𐌹𐍂𐍄𐍉𐌽𐌰 𐌹𐌶𐍅𐌰𐍂𐌰 𐌿(𐌽)𐍆𐌰𐌹𐍂𐌹𐌽𐍉𐌽𐌰 𐌹𐌽 𐍅𐌴𐌹𐌷𐌹𐌸𐌰𐌹 𐍆𐌰𐌿𐍂𐌰 𐌲𐌿𐌳𐌰 𐌾𐌰𐌷 𐌰𐍄𐍄𐌹𐌽 𐌿𐌽𐍃𐌰𐍂𐌰𐌼𐌼𐌰 𐌹𐌽 𐌵𐌿𐌼𐌰 𐍆𐍂𐌰𐌿𐌾𐌹𐌽𐍃 𐌿𐌽𐍃𐌰𐍂𐌹𐍃 𐌹𐌴𐍃𐌿𐌹𐍃 𐍇𐍂𐌹𐍃𐍄𐌰𐌿𐍃 𐌼𐌹𐌸 𐌰𐌻𐌻𐌰𐌹𐌼 𐌸𐌰𐌹𐌼 𐍅𐌴𐌹𐌷𐌰𐌼 𐍃𐌴𐌹𐌽𐌰𐌹𐌼.',
    },
    4: {
        1: '𐌸𐌰𐌽𐌽𐌿 𐌽𐌿, 𐌱𐍂𐍉𐌸𐍂𐌾𐌿𐍃, 𐌰𐌽𐌰𐌷𐌰𐌹𐍄𐌰𐌼 𐌱𐌹𐌳𐌰𐌹 𐌹𐌶𐍅𐌹𐍃 𐌾𐌰𐌷 𐌱𐌹𐌳𐌾𐌰𐌼 𐌹𐌽 𐍆𐍂𐌰𐌿𐌾𐌹𐌽 𐌹𐌴𐍃𐌿𐌰, 𐌴𐌹 𐍃𐍅𐌰𐍃𐍅𐌴 𐌰𐌽𐌳𐌽𐌴𐌼𐌿𐌸 𐌰𐍄 𐌿𐌽𐍃 𐍈𐌰𐌹𐍅𐌰 𐍃𐌺𐌿𐌻𐌿𐌸 𐌲𐌰𐌲𐌲𐌰𐌽 𐌾𐌰𐌷 𐌲𐌰𐌻𐌴𐌹𐌺𐌰𐌽 𐌲𐌿𐌳𐌰, 𐍃𐍅𐌰[𐍃𐍅𐌴] 𐌾𐌰𐌷 𐌲𐌰𐌲𐌲𐌰𐌹𐌸 𐌾𐌰𐌷 𐌲𐌰𐌰𐌿𐌺𐌰𐌹𐌸 𐌼𐌰𐌹𐍃.',
        2: '𐍅𐌹𐍄𐌿𐌸 𐌰𐌿𐌺 𐍈𐌰𐍂𐌾𐍉𐍃 𐌰𐌽𐌰𐌱𐌿𐍃𐌽𐌹𐌽𐍃 𐌰𐍄𐌲𐌴𐌱𐌿𐌼 𐌹𐌶𐍅𐌹𐍃 𐌸𐌰𐌹𐍂𐌷 𐍆𐍂𐌰𐌿𐌾𐌰𐌽 𐌹𐌴𐍃𐌿 𐍇𐍂𐌹𐍃𐍄𐌿.',
        3: '𐌸𐌰𐍄𐌰 𐌰𐌿𐌺 𐌹𐍃𐍄 𐍅𐌹𐌻𐌾𐌰 𐌲𐌿𐌳𐌹𐍃, 𐍅𐌴𐌹𐌷𐌹𐌸𐌰 𐌹𐌶𐍅𐌰𐍂𐌰, 𐌴𐌹 𐌲𐌰𐌷𐌰𐌱𐌰𐌹𐌸 𐌹𐌶𐍅𐌹𐍃 𐌰𐍆 𐌺𐌰𐌻𐌺𐌹𐌽𐌰𐍃𐍃𐌰𐌿[𐍃],',
        4: '𐌴𐌹 𐍅𐌹𐍄𐌹 𐍈𐌰𐍂𐌾𐌹𐌶𐌿𐌷 𐌹𐌶𐍅𐌰𐍂𐌰 𐌲𐌰𐍃𐍄𐌰𐌻𐌳𐌰𐌽 𐍃𐌴𐌹𐌽 𐌺𐌰𐍃 𐌹𐌽 𐍅𐌴𐌹𐌷𐌹𐌸𐌰𐌹 𐌾𐌰𐌷 𐍃𐍅𐌴𐍂𐌹𐌸𐌰𐌹,',
        5: '𐌽𐌹 𐌹𐌽 𐌲𐌰𐌹𐍂𐌿𐌽𐌾𐌰 𐌻𐌿𐍃𐍄𐌰𐌿𐍃, 𐍃𐍅𐌰𐍃𐍅𐌴 𐌾𐌰𐌷 𐌸𐌹𐌿𐌳𐍉𐍃 𐌸𐍉𐌶𐌴𐌹 𐌽𐌹 𐌺𐌿𐌽𐌽𐌿𐌽 𐌲𐌿𐌸,',
        6: '𐌴𐌹 𐍈𐌰𐍃 𐌽𐌹 𐌿𐍆𐌰𐍂𐌲𐌰𐌲𐌲𐌰𐌹 𐌽𐌹𐌷 𐌱𐌹 𐍆𐌰𐌹𐌷𐌿 _𐍉𐌻_ 𐌱𐍂𐍉𐌸𐌰𐍂 𐍃𐌴𐌹𐌽𐌰𐌽𐌰, 𐌿𐌽𐍄𐌴 𐍆𐍂𐌰𐍅𐌴𐌹𐍄𐌰𐌽𐌳𐍃 𐍆𐍂𐌰𐌿𐌾𐌰 𐌹𐍃𐍄 𐌰𐌻𐌻𐌰𐌹𐌶𐌴, 𐍃𐍅𐌰𐍃𐍅𐌴 𐌾𐌰𐌷 𐍆𐌰𐌿𐍂𐌰𐌵𐌴𐌸𐌿𐌼 𐌹𐌶𐍅𐌹𐍃 𐌾𐌰𐌷 𐍅𐌴𐌹𐍄𐍅𐍉𐌳𐌹𐌳𐌴𐌳𐌿𐌼.',
        7: '𐌿𐌽𐍄𐌴 𐌽𐌹 𐌻𐌰𐌸𐍉𐌳𐌰 𐌿𐌽𐍃 𐌲𐌿𐌸 𐌳𐌿 𐌿𐌽𐌷𐍂𐌰𐌹𐌽𐌹𐌸𐌰𐌹, 𐌰𐌺 𐌹𐌽 𐍅𐌴𐌹𐌷𐌹𐌸𐌰.',
        8: '𐌹𐌽𐌿𐌷 𐌸𐌹𐍃 𐌽𐌿 𐍃𐌰𐌴𐌹 𐌿𐍆𐌱𐍂𐌹𐌺𐌹𐌸, 𐌽𐌹 𐌼𐌰𐌽𐌽 𐌿𐍆𐌱𐍂𐌹𐌺𐌹𐌸, 𐌰𐌺 𐌲𐌿𐌳𐌰, 𐍃𐌰𐌴𐌹 𐌲𐌰𐍆 𐌰𐌷𐌼𐌰𐌽 𐍃𐌴𐌹𐌽𐌰𐌽𐌰 𐍅𐌴𐌹𐌷𐌰𐌽𐌰 𐌹𐌶𐍅𐌹𐍃.',
        9: '𐌰𐌸𐌸𐌰𐌽 𐌱𐌹 𐌱𐍂𐍉𐌸𐍂𐌿𐌻𐌿𐌱𐍉𐌽 𐌽𐌹 𐌸𐌰𐌿𐍂𐌱𐌿𐌼 𐌼𐌴𐌻𐌾𐌰𐌽 𐌹𐌶𐍅𐌹𐍃, 𐌿𐌽𐍄𐌴 𐍃𐌹𐌻𐌱𐌰𐌽𐍃 𐌾𐌿𐍃 𐌰𐍄 𐌲𐌿𐌳𐌰 𐌿𐍃𐌻𐌰𐌹𐍃𐌹𐌳𐌰𐌹 𐍃𐌹𐌾𐌿𐌸 𐌳𐌿 𐍆𐍂𐌹𐌾𐍉𐌽 𐌹𐌶𐍅𐌹𐍃 𐌼𐌹𐍃𐍃𐍉.',
        10: '𐌾𐌰𐌷 𐌰𐌿𐌺 𐍄𐌰𐌿𐌾𐌹𐌸 𐌸𐌰𐍄𐌰 𐌹𐌽 𐌰𐌻𐌻𐌰𐌽𐍃 𐌱𐍂𐍉𐌸𐍂𐌿𐌽𐍃 𐌹𐌽 𐌰𐌻𐌻𐌰𐌹 𐌼𐌰𐌺𐌹𐌳𐍉𐌽𐌰𐌹; 𐌰𐌸𐌸𐌰𐌽 𐌱𐌹𐌳𐌾𐌰𐌼 𐌹𐌶𐍅𐌹𐍃, 𐌱𐍂𐍉𐌸𐍂𐌾𐌿𐍃, 𐌱𐌹𐌰𐌿𐌺𐌽𐌰𐌽 𐌼𐌰𐌹𐍃',
        11: '𐌾𐌰𐌷 𐌱𐌹𐌰𐍂𐌱𐌰𐌹𐌳𐌾𐌰𐌽 𐌰𐌽𐌰𐌵𐌰𐌻 𐌾𐌰𐌷 𐍄𐌰𐌿𐌾𐌰𐌽 𐍃𐍅𐌴𐍃𐌰 𐌾𐌰𐌷 𐍅𐌰𐌿𐍂𐌺𐌾𐌰𐌽 𐌷𐌰𐌽𐌳𐌿𐌼 𐌹𐌶𐍅𐌰𐍂𐌰𐌹𐌼, 𐍃𐍅𐌰𐍃𐍅𐌴 𐌾𐌰𐌷 𐌹𐌶𐍅𐌹𐍃 𐌰𐌽𐌰𐌱𐌿𐌳𐌿𐌼,',
        12: '𐌴𐌹 𐌲𐌰𐌲𐌲𐌰𐌹𐌸 𐌲𐌰𐍆𐌴𐌷𐌰𐌱𐌰 𐌳𐌿 𐌸𐌰𐌹𐌼 𐌸𐌰𐌹𐌴𐌹 𐌿𐍄𐌰 𐍃𐌹𐌽𐌳 𐌾𐌰𐌷 𐌽𐌹 𐌰𐌹𐌽𐌹𐍃𐌷𐌿𐌽 𐍈𐌹𐍃 𐌸𐌰𐌿𐍂𐌱𐌴𐌹𐌸.',
        13: '𐌰𐌸𐌸𐌰𐌽 𐌽𐌹 𐍅𐌹𐌻𐌴𐌹𐌼𐌰 𐌹𐌶𐍅𐌹𐍃 𐌿𐌽𐍅𐌴𐌹𐍃𐌰𐌽𐍃, 𐌱𐍂𐍉𐌸𐍂𐌾𐌿𐍃, 𐌱𐌹 𐌸𐌰𐌽𐍃 𐌰𐌽𐌰𐍃𐌻𐌴𐍀𐌰𐌽𐌳𐌰𐌽𐍃, 𐌴𐌹 𐌽𐌹 𐍃𐌰𐌿𐍂𐌲𐌰𐌹𐌸 𐍃𐍅𐌴 𐌸𐌰𐌹 𐌰𐌽𐌸𐌰𐍂𐌰𐌹 𐌸𐌰𐌹𐌴𐌹 𐌽𐌹 𐌷𐌰𐌱𐌰𐌽𐌳 𐍅𐌴𐌽.',
        14: '𐌿𐌽𐍄𐌴 𐌾𐌰𐌱𐌰𐌹 𐌲𐌰𐌻𐌰𐌿𐌱𐌾𐌰𐌼 𐌸𐌰𐍄𐌴𐌹 𐌹𐌴𐍃𐌿𐍃 𐌲𐌰𐍃𐍅𐌰𐌻𐍄 𐌾𐌰𐌷 𐌿𐍃𐍃𐍄𐍉𐌸, 𐍃𐍅𐌰 𐌾𐌰𐌷 𐌲𐌿𐌸 𐌸𐌰𐌽𐍃 𐌸𐌰𐌹𐌴𐌹 𐌰𐌽𐌰𐍃𐌰𐌹𐍃𐌻𐌴𐍀𐌿𐌽 𐌸𐌰𐌹𐍂𐌷 𐌹𐌴𐍃𐌿 𐍄𐌹𐌿𐌷[𐌰]𐌹𐌸 𐌼𐌹𐌸 𐌹𐌼𐌼𐌰.',
        15: '𐌸𐌰𐍄𐌿𐌸~𐌸𐌰𐌽 𐌹𐌶𐍅𐌹𐍃 𐌵𐌹𐌸𐌰𐌼 𐌹𐌽 𐍅𐌰𐌿𐍂𐌳𐌰 𐍆𐍂𐌰𐌿𐌾𐌹𐌽𐍃, 𐌸𐌰𐍄𐌴𐌹 𐍅𐌴𐌹𐍃 𐌸𐌰𐌹 𐌻𐌹𐌱𐌰𐌽𐌳𐌰𐌽𐍃, 𐌸𐌰𐌹 𐌱𐌹𐌻𐌰𐌹𐌱𐌹𐌳𐌰𐌽𐍃 𐌹𐌽 𐌵𐌿𐌼𐌰 𐍆𐍂𐌰𐌿𐌾𐌹𐌽𐍃 𐌽𐌹 𐌱𐌹𐍃𐌽𐌹𐍅𐌰𐌼 𐍆𐌰𐌿𐍂 𐌸𐌰𐌽𐍃 𐌰𐌽𐌰𐍃𐌻𐌴𐍀𐌰𐌽𐌳𐌰𐌽𐍃;',
        16: '𐌿𐌽𐍄𐌴 𐍃𐌹𐌻𐌱𐌰 𐍆𐍂𐌰𐌿𐌾𐌰 𐌹𐌽 𐌷𐌰𐌹𐍄𐌾𐌰𐌹, 𐌹𐌽 𐍃𐍄𐌹𐌱𐌽𐌰𐌹 𐌰𐍂𐌺𐌰𐌲𐌲𐌹𐌻𐌰𐌿𐍃 𐌾𐌰𐌷 𐌹𐌽 𐌸𐌿𐍄𐌷𐌰𐌿𐍂𐌽𐌰 𐌲𐌿𐌳𐌹𐍃 𐌳𐌰𐌻𐌰𐌸 𐌰𐍄𐍃𐍄𐌴𐌹𐌲𐌹𐌸 𐌰𐍆 𐌷𐌹𐌼𐌹𐌽𐌰 𐌾𐌰𐌷 𐌳𐌰𐌿𐌸𐌰𐌽𐍃 𐌸𐌰𐌹 𐌹𐌽 𐍇𐍂𐌹𐍃𐍄𐌰𐌿 𐌿𐍃𐍃𐍄𐌰𐌽𐌳𐌰𐌽𐌳 𐍆𐌰𐌿𐍂𐌸𐌹𐍃.',
        17: '𐌸𐌰𐌸𐍂𐍉 𐌸𐌰𐌽 𐍅𐌴𐌹𐍃 𐌸𐌰𐌹 𐌻𐌹𐌱𐌰𐌽𐌳𐌰𐌽𐍃, 𐌸𐌰𐌹 𐌰𐍆𐌻𐌹𐍆𐌽𐌰𐌽𐌳𐌰𐌽𐍃 𐍃𐌿𐌽𐍃 𐌼𐌹𐌸 𐌹𐌼𐌼𐌰 𐍆𐍂𐌰𐍅𐌹𐌻𐍅𐌰𐌽𐌳𐌰 𐌹𐌽 𐌼𐌹𐌻𐌷𐌼𐌰𐌼 𐌳𐌿 𐌲𐌰𐌼𐍉𐍄𐌾𐌰𐌽 𐍆𐍂𐌰𐌿𐌾𐌹𐌽 𐌹𐌽 𐌻𐌿𐍆𐍄𐌰𐌿 𐌾𐌰𐌷 𐍆𐍂𐌰𐌼𐍅𐌹𐌲𐌹𐍃 𐌼𐌹𐌸 𐍆𐍂𐌰𐌿𐌾𐌹𐌽 𐍅𐌰𐌹𐍂𐌸𐌰𐌼.',
        18: '𐍃𐍅𐌰𐌴𐌹 𐌽𐌿 𐌸𐍂𐌰𐍆𐍃𐍄𐌴𐌹𐌸 𐌹𐌶𐍅𐌹𐍃 𐌼𐌹𐍃𐍃𐍉 𐌹𐌽 𐌸𐌰𐌹𐌼 𐍅𐌰𐌿𐍂𐌳𐌰𐌼.',
    },
    5: {
        1: '𐌰𐌸𐌸𐌰𐌽 𐌱𐌹 𐌸𐍉 𐌸𐌴𐌹𐌷𐍃𐌰 𐌾𐌰𐌷 𐌼𐌴𐌻𐌰, 𐌱𐍂𐍉𐌸𐍂𐌾𐌿𐍃, 𐌽𐌹 𐌸𐌰𐌿𐍂𐌱𐌿𐌼 𐌴𐌹 𐌹𐌶𐍅𐌹𐍃 𐌼𐌴𐌻𐌾𐌰𐌹𐌼𐌰;',
        2: '𐌿𐌽𐍄𐌴 𐍃𐌹𐌻𐌱𐌰𐌽𐍃 𐌲𐌻𐌰𐌲𐌲𐍅𐍉 𐍅𐌹𐍄𐌿𐌸 𐌸𐌰𐍄𐌴𐌹 𐌳𐌰𐌲𐍃 𐍆𐍂𐌰𐌿𐌾𐌹𐌽𐍃 𐍃𐍅𐌴 𐌸𐌹𐌿𐌱𐍃 𐌹𐌽 𐌽𐌰𐌷𐍄 𐍃𐍅𐌰 𐌵𐌹𐌼𐌹𐌸.',
        3: '𐌸𐌰𐌽 𐌵𐌹𐌸𐌰𐌽𐌳: 𐌲𐌰𐍅𐌰𐌹𐍂𐌸𐌹 𐌾𐌰𐌷 𐍄𐌿𐌻𐌲𐌹𐌸𐌰, 𐌸𐌰𐌽𐌿𐌷 𐌿𐌽𐍅𐌴𐌽𐌹𐌲𐌲𐍉 𐌹𐌽𐍃 𐌱𐌹𐌵𐌹𐌼𐌹𐌸 𐍆𐍂𐌰𐌻𐌿𐍃𐍄𐍃 𐍃𐍅𐌰𐍃𐍅𐌴 𐍃𐌰𐌹𐍂 𐌵𐌹𐌸𐌿𐌷𐌰𐍆𐍄𐍉𐌽, 𐌾𐌰𐌷 𐌽𐌹 𐌿𐌽𐌸𐌰𐌸𐌻𐌹𐌿𐌷𐌰𐌽𐌳.',
        4: '𐌰𐌸𐌸𐌰𐌽 𐌾𐌿𐍃, 𐌱𐍂𐍉𐌸𐍂𐌾𐌿𐍃, 𐌽𐌹 𐍃𐌹𐌾𐌿𐌸 𐌹𐌽 𐍂𐌹𐌵𐌹𐌶𐌰, 𐌴𐌹 𐍃𐌰 𐌳𐌰𐌲𐍃 𐌹𐌶𐍅𐌹𐍃 𐍃𐍅𐌴 𐌸𐌹𐌿𐌱𐍃 𐌲𐌰𐍆𐌰𐌷𐌰𐌹;',
        5: '𐌿𐌽𐍄𐌴 𐌰𐌻𐌻𐌰𐌹 𐌾𐌿𐍃 𐍃𐌿𐌽𐌾𐌿𐍃 𐌻𐌹𐌿𐌷𐌰𐌳𐌹𐍃 𐍃𐌹𐌾𐌿𐌸 𐌾𐌰𐌷 𐍃𐌿𐌽𐌾𐌿𐍃 𐌳𐌰𐌲𐌹𐍃; 𐌽𐌹 𐍃𐌹𐌿𐌸 𐌽𐌰𐌷𐍄𐍃 𐌽𐌹 𐍂𐌹𐌵𐌹𐌶𐌹𐍃.',
        6: '𐌸𐌰𐌽𐌽𐌿 𐌽𐌿 𐌽𐌹 𐍃𐌻𐌴𐍀𐌰𐌹𐌼𐌰 𐍃𐍅𐌴 𐌸𐌰𐌹 𐌰𐌽𐌸𐌰𐍂𐌰𐌹, 𐌰𐌺 𐍅𐌰𐌺𐌰𐌹𐌼𐌰 𐌾𐌰𐌷 𐍅𐌰𐍂𐌰𐌹 𐍃𐌹𐌾𐌰𐌹𐌼𐌰;',
        7: '𐌿𐌽𐍄𐌴 𐌸𐌰𐌹𐌴𐌹 𐍃𐌻𐌴𐍀𐌰𐌽𐌳, 𐌽𐌰𐌷𐍄 𐍃𐌻𐌴𐍀𐌰𐌽𐌳, 𐌾𐌰𐌷 𐌸𐌰𐌹𐌴𐌹 𐌳𐍂𐌿𐌲𐌺𐌰𐌽𐌰𐌹 𐍅𐌰𐌹𐍂𐌸𐌰𐌽𐌳, 𐌽𐌰𐌷𐍄𐍃 𐌳𐍂𐌿𐌲𐌺𐌰𐌽𐌰𐌹 𐍅𐌰𐌹𐍂𐌸𐌰𐌽𐌳.',
        8: '𐌹𐌸 𐍅𐌴𐌹𐍃 𐌳𐌰𐌲𐌹𐍃 𐍅𐌹𐍃𐌰𐌽𐌳𐌰𐌽𐍃 𐌿𐍃𐍃𐌺𐌰𐍅𐌰𐌹 𐍃𐌹𐌾𐌰𐌹𐌼𐌰, 𐌲𐌰𐌷𐌰𐌼𐍉𐌳𐌰𐌹 𐌱𐍂𐌿𐌽𐌾𐍉𐌽 𐌲𐌰𐌻𐌰𐌿𐌱𐌴𐌹𐌽𐌰𐌹𐍃 𐌾𐌰𐌷 𐍆𐍂𐌹𐌰𐌸𐍅𐍉𐍃 𐌾𐌰𐌷 𐌷𐌹𐌻𐌼𐌰 𐍅𐌴𐌽𐌰𐌹 𐌽𐌰𐍃[𐍃]𐌴𐌹𐌽𐌰𐌹𐍃.',
        9: '𐌿𐌽𐍄𐌴 𐌽𐌹 𐍃𐌰𐍄𐌹𐌳𐌰 𐌿𐌽𐍃 𐌲𐌿𐌸 𐌹𐌽 𐌷𐌰𐍄𐌹𐍃, 𐌰𐌺 𐌳𐌿 𐌲𐌰𐍆𐍂𐌴𐌹𐌳𐌴𐌹𐌽𐌰𐌹 𐌲𐌰𐌽𐌹𐍃𐍄𐌰𐌹𐍃, 𐌸𐌰𐌹𐍂𐌷 𐍆𐍂𐌰𐌿𐌾𐌰𐌽 𐌿𐌽𐍃𐌰𐍂𐌰𐌽𐌰 𐌹𐌴𐍃𐌿 𐍇𐍂𐌹𐍃𐍄𐌿,',
        10: '𐍃𐌰𐌴𐌹 𐌲𐌰𐍃𐍅𐌰𐌻𐍄 𐍆𐌰𐌿𐍂 𐌿𐌽𐍃, 𐌴𐌹, 𐌾𐌰𐌸𐌸𐌴 𐍃𐌻𐌴𐍀𐌰𐌹𐌼𐌰 𐌾𐌰𐌸𐌸𐌴 𐍅𐌰𐌺𐌰𐌹𐌼𐌰, 𐍃𐌰𐌼𐌰𐌽𐌰 𐌼𐌹𐌸 𐌹𐌼𐌼𐌰 𐌻𐌹𐌱𐌰𐌹𐌼𐌰.',
        11: '𐌹𐌽𐌿𐌷 𐌸𐌹𐍃 𐌸𐍂𐌰𐍆𐍃𐍄𐌴𐌹𐌸 𐌹𐌶𐍅𐌹𐍃 𐌼𐌹𐍃𐍃𐍉 𐌾𐌰𐌷 𐍄𐌹𐌼𐍂𐌾𐌰𐌹𐌸 𐌰𐌹𐌽𐍈𐌰𐍂𐌾𐌹𐌶𐌿𐌷 𐌰𐌽𐌸𐌰𐍂 𐌰𐌽𐌸𐌰𐍂𐌰𐌽𐌰, 𐍃𐍅𐌰𐍃𐍅𐌴 𐌾𐌰𐌷 𐍄𐌰𐌿𐌾𐌹𐌸.',
        12: '𐌰𐌸𐌸𐌰𐌽 𐌱𐌹𐌳𐌾𐌰𐌼 𐌹𐌶𐍅𐌹𐍃, 𐌱𐍂𐍉𐌸𐍂𐌾𐌿𐍃, 𐌺𐌿𐌽𐌽𐌰𐌽 𐌸𐌰𐌽𐍃 𐌰𐍂𐌱𐌰𐌹𐌳𐌾𐌰𐌽𐌳𐌰𐌽𐍃 𐌹𐌽 𐌹𐌶𐍅𐌹𐍃 𐌾𐌰𐌷 𐍆𐌰𐌿𐍂𐍃𐍄𐌰𐍃𐍃𐌾𐌰𐌽𐍃 𐌹𐌶𐍅𐌰𐍂𐌰𐌽𐍃 𐌹𐌽 𐍆𐍂𐌰𐌿𐌾𐌹𐌽',
        13: '𐍃𐍅𐌴𐍂𐌰𐌹𐌸 𐌹𐌽𐍃 𐌿𐍆𐌰𐍂𐌰𐍃𐍃𐌰𐌿 𐌹𐌽 𐍆𐍂𐌹𐌰𐌸𐍅𐌰𐌹 𐌹𐌽 𐍅𐌰𐌿𐍂𐍃𐍄𐍅𐌹𐍃 𐌹𐌶𐌴 𐌾𐌰𐌷 𐌲𐌰𐍅𐌰𐌹𐍂𐌸𐌹 𐌷𐌰𐌱𐌰𐌹𐌸 𐌹𐌽 𐌹𐌶𐍅𐌹𐍃.',
        14: '𐌱𐌹𐌳𐌾𐌰𐌼𐌿𐌸~𐌸𐌰𐌽 𐌹𐌶𐍅𐌹𐍃, 𐌱𐍂𐍉𐌸𐍂𐌾𐌿𐍃, 𐍄𐌰𐌻𐌶𐌾𐌰𐌹𐌸 𐌸𐌰𐌽𐍃 𐌿𐌽𐌲𐌰𐍄𐌰𐍃𐍃𐌰𐌽𐍃, 𐌸𐍂𐌰𐍆𐍃𐍄𐌾𐌰𐌹𐌸 𐌸𐌰𐌽𐍃 𐌲𐍂𐌹𐌽𐌳𐌰𐍆𐍂𐌰𐌸𐌾𐌰𐌽𐍃, 𐌿𐍃𐌸𐌿𐌻𐌰𐌹𐌸 𐌸𐌰𐌽𐍃 𐍃𐌹𐌿𐌺𐌰𐌽𐍃, 𐌿𐍃𐌱𐌴𐌹𐍃𐌽𐌴𐌹𐌲𐌰𐌹 𐍃𐌹𐌾𐌰𐌹𐌸 𐍅𐌹𐌸𐍂𐌰 𐌰𐌻𐌻𐌰𐌽𐍃.',
        15: '𐍃𐌰𐌹𐍈𐌹𐌸 𐌹𐌱𐌰𐌹 𐍈𐌰𐍃 𐌿𐌱𐌹𐌻 𐌿𐌽𐌳 𐌿𐌱𐌹𐌻𐌰𐌼𐌼𐌰 𐍈𐌰𐌼𐌼𐌰 𐌿𐍃𐌲𐌹𐌻𐌳𐌰𐌹, 𐌰𐌺 𐍃𐌹𐌽𐍄𐌴𐌹𐌽𐍉 𐌸𐌹𐌿𐌸 𐌻𐌰𐌹𐍃𐍄𐌾𐌰𐌹𐌸 𐌼𐌹𐌸 𐌹𐌶𐍅𐌹𐍃 𐌼𐌹𐍃𐍃𐍉 𐌾𐌰𐌷 𐍅𐌹𐌸𐍂𐌰 𐌰𐌻𐌻𐌰𐌽𐍃.',
        16: '𐍃𐌹𐌽𐍄𐌴𐌹𐌽𐍉 𐍆𐌰𐌲𐌹𐌽𐍉𐌸 𐌹𐌽 𐍆𐍂𐌰𐌿𐌾𐌹𐌽.',
        17: '𐌿𐌽𐍃𐍅𐌴𐌹𐌱𐌰𐌽𐌳(𐌰𐌽𐍃) 𐌱𐌹𐌳𐌾𐌰𐌹𐌸;',
        18: '𐌹𐌽 𐌰𐌻𐌻𐌰𐌼𐌼𐌰 𐌰𐍅𐌹𐌻𐌹(𐌿𐌳𐍉𐌸). 𐌸𐌰𐍄𐌰 𐌰𐌿𐌺 𐌹𐍃𐍄 𐍅𐌹𐌻𐌾𐌰 𐌲𐌿𐌳𐌹𐍃 𐌹𐌽 𐍇𐍂𐌹𐍃𐍄𐌰𐌿 𐌹𐌴𐍃𐌿 𐌹𐌽 𐌹𐌶𐍅𐌹𐍃.',
        19: '𐌰𐌷𐌼𐌰𐌽 𐌽𐌹 𐌰𐍆𐍈𐌰𐍀𐌾𐌰𐌹𐌸.',
        20: '𐍀𐍂𐌰𐌿𐍆𐌴𐍄𐌾𐌰𐌼 𐌽𐌹 𐍆𐍂𐌰𐌺𐌿𐌽𐌽𐌴𐌹𐌸.',
        21: '𐌰𐌸𐌸𐌰𐌽 𐌰𐌻𐌻 𐌿𐍃𐌺𐌹𐌿𐍃𐌰𐌹𐌸; 𐌸𐌰𐍄𐌴𐌹 𐌲𐍉𐌳 𐍃𐌹𐌾𐌰𐌹, 𐌲𐌰𐌷𐌰𐌱𐌰𐌹𐌸.',
        22: '.... 𐌿𐌱𐌹𐌻𐌰𐌹𐌶𐍉 𐌰𐍆𐌷𐌰𐌱𐌰𐌹𐌸 𐌹𐌶𐍅𐌹𐍃. 𐌰𐍆 𐌰𐌻𐌻𐌰𐌼𐌼𐌰 𐍅𐌰𐌹𐌷𐍄𐌴 𐌿𐌱𐌹𐌻𐌰𐌹𐌶𐍉 𐌰𐍆𐌷𐌰𐌱𐌰𐌹𐌸 𐌹𐌶𐍅𐌹𐍃.',
        23: '𐌰𐌸𐌸𐌰𐌽 𐍃𐌹𐌻𐌱𐌰 𐌲𐌿𐌸 𐌲𐌰𐍅𐌰𐌹𐍂𐌸𐌾𐌹𐍃 𐌲𐌰𐍅𐌴𐌹𐌷𐌰𐌹 𐌹𐌶𐍅𐌹𐍃 𐌰𐌻𐌻𐌰𐌽𐌳𐌾𐍉 𐌾𐌰𐌷 𐌲𐌰𐌷𐌰𐌹𐌻𐌰𐌽𐌰 𐌹𐌶𐍅𐌰𐍂𐌰𐌽𐌰 𐌰𐌷𐌼𐌰𐌽, 𐌾𐌰𐌷 𐍃𐌰𐌹𐍅𐌰𐌻𐌰 𐌾𐌰𐌷 𐌻𐌴𐌹𐌺 𐌿𐌽𐍆𐌰𐌹𐍂𐌹𐌽𐍉𐌽𐌰 𐌹𐌽 𐌵𐌿𐌼𐌰 𐍆𐍂𐌰𐌿𐌾𐌹𐌽𐍃 𐌿𐌽𐍃𐌰𐍂𐌹𐍃 𐌹𐌴𐍃𐌿𐌹𐍃 𐍇𐍂𐌹𐍃𐍄𐌰𐌿𐍃 𐌲𐌰𐍆𐌰𐍃𐍄𐌰𐌹𐌽𐌳𐌰𐌿. 𐌰𐌸𐌸𐌰𐌽 𐍃𐌹𐌻𐌱𐌰 𐌲𐌿𐌸 𐌲𐌰𐍅𐌰𐌹𐍂𐌸𐌾𐌹𐍃 𐌲𐌰𐍅𐌴𐌹𐌷𐌰𐌹 𐌹𐌶𐍅𐌹𐍃 𐌰𐌻𐌻𐌰𐌽𐌳𐌾𐍉 𐌾𐌰𐌷 𐌲𐌰𐌷𐌰𐌹𐌻𐌰𐌽𐌰 𐌹𐌶𐍅𐌰𐍂𐌰𐌽𐌰 𐌰𐌷𐌼𐌰𐌽, 𐌾𐌰𐌷 𐍃𐌰𐌹𐍅𐌰𐌻𐌰 𐌾𐌰𐌷 𐌻𐌴𐌹𐌺 𐌿𐍃𐍆𐌰𐌹𐍂𐌹𐌽𐍉𐌽𐌰 𐌹𐌽 𐌵𐌿𐌼𐌰 𐍆𐍂𐌰𐌿𐌾𐌹𐌽𐍃 𐌿𐌽𐍃𐌰𐍂𐌹𐍃 𐌹𐌴𐍃𐌿𐌹𐍃 𐍇𐍂𐌹𐍃𐍄𐌰𐌿𐍃 𐌲𐌰𐍆𐌰𐍃𐍄𐌰𐌹𐌽𐌳𐌰𐌿.',
        24: '𐍄𐍂𐌹𐌲𐌲𐍅𐍃 𐍃𐌰𐌴𐌹 𐌻𐌰𐌸𐍉𐌳𐌰 𐌹𐌶𐍅𐌹𐍃, 𐍃𐌰𐌴𐌹 𐌾𐌰𐌷 𐍄𐌰𐌿𐌾𐌹𐌸. 𐍄𐍂𐌹𐌲𐌲𐍅𐍃 𐍃𐌰𐌴𐌹 𐌻𐌰𐌸𐍉𐌳𐌰 𐌹𐌶𐍅𐌹𐍃, 𐍃𐌰𐌴𐌹 𐌾𐌰𐌷 𐍄𐌰𐌿𐌾𐌹𐌸.',
        25: '𐌱𐍂𐍉𐌸𐍂𐌾𐌿𐍃, 𐌱𐌹𐌳𐌾𐌰𐌹𐌸𐌿𐌸~𐌸𐌰𐌽 𐌾𐌰𐌷 𐌱𐌹 𐌿𐌽𐍃. 𐌱𐍂𐍉𐌸𐍂𐌾𐌿𐍃, 𐌱𐌹𐌳𐌾𐌰𐌹𐌸𐌿𐌸~𐌸𐌰𐌽 𐌾𐌰𐌷 𐌱𐌹 𐌿𐌽𐍃.',
        26: '𐌲𐍉𐌻𐌾𐌰𐌹𐌸 𐌱𐍂𐍉𐌸𐍂𐌿𐌽𐍃 𐌰𐌻𐌻𐌰𐌽𐍃 𐌹𐌽 𐌲𐌰𐍆𐍂𐌹𐌾𐍉𐌽𐌰𐌹 𐍅𐌴𐌹𐌷𐌰𐌹. 𐌲𐍉𐌻𐌾𐌰𐌹𐌸 𐌱𐍂𐍉𐌸𐍂𐌿𐌽𐍃 𐌰𐌻𐌻𐌰𐌽𐍃 𐌹𐌽 𐌲𐌰𐍆𐍂𐌹𐌾𐍉𐌽𐌰𐌹 𐍅𐌴𐌹𐌷𐌰𐌹.',
        27: '𐌱𐌹𐍃𐍅𐌰𐍂𐌰 𐌹𐌶𐍅𐌹𐍃 𐌹𐌽 𐍆𐍂𐌰𐌿𐌾𐌹𐌽 𐌴𐌹 𐌿𐍃𐍃𐌹𐌲𐌲𐍅𐌰𐌹𐌳𐌰𐌿 𐍃𐍉 𐌰𐌹𐍀𐌹𐍃𐍄𐌰𐌿𐌻𐌴 𐌰𐌻𐌻𐌰𐌹𐌼 𐌸𐌰𐌹𐌼 𐍅𐌴𐌹𐌷𐌰𐌼 𐌱𐍂𐍉𐌸𐍂𐌿𐌼. 𐌱𐌹𐍃𐍅𐌰𐍂𐌰 𐌹𐌶𐍅𐌹𐍃 𐌹𐌽 𐍆𐍂𐌰𐌿𐌾𐌹𐌽 𐌴𐌹 𐌿𐍃𐍃𐌹𐌲𐌲𐍅𐌰𐌹𐌳𐌰𐌿 𐍃𐍉 𐌰𐌹𐍀𐌹𐍃𐍄𐌰𐌿𐌻𐌴 𐌸𐌰𐌹𐌼 𐍅𐌴𐌹𐌷𐌰𐌼 𐌱𐍂𐍉𐌸𐍂𐌿𐌼.',
        28: '𐌰𐌽𐍃𐍄𐍃 𐍆𐍂𐌰𐌿𐌾𐌹𐌽𐍃 𐌿𐌽𐍃𐌰𐍂𐌹𐍃 𐌹𐌴𐍃𐌿𐌹𐍃 𐍇𐍂𐌹𐍃𐍄𐌰𐌿𐍃 𐌼𐌹𐌸 𐌹𐌶𐍅𐌹𐍃. 𐌰𐌼𐌴𐌽. 𐌰𐌽𐍃𐍄𐍃 𐍆𐍂𐌰𐌿𐌾𐌹𐌽𐍃 𐌿𐌽𐍃𐌰𐍂𐌹𐍃 𐌹𐌴𐍃𐌿𐌹𐍃 𐍇𐍂𐌹𐍃𐍄𐌰𐌿𐍃 𐌼𐌹𐌸 𐌹𐌶𐍅𐌹𐍃. 𐌰𐌼𐌴𐌽. [(I Thessalonians 5:29) 𐌳𐌿 𐌸𐌰(𐌹𐍃𐍃𐌰𐌻𐌰𐌿𐌽𐌴𐌹𐌺𐌰𐌹)𐌿𐌼 ·𐌰· (𐌿𐍃)𐍄𐌰𐌿𐌷.]',
    },
}
